def count_odd_digit_numbers(N):
    # Helper function to count numbers with odd digits up to a given number of digits
    def count_odd_digits_up_to_digit_length(digit_length):
        if digit_length == 0:
            return 0
        if digit_length == 1:
            return 9  # 1 to 9, all have odd digits
        if digit_length % 2 == 0:
            # Even digit length: all numbers have even digits
            return 0
        else:
            # Odd digit length: count numbers with odd digits
            total = 0
            for i in range(1, digit_length + 1):
                if i % 2 == 1:
                    total += 9 * (10 ** (i - 1))
            return total

    # Calculate the number of digits in N
    num_digits = len(str(N))

    # Count numbers with odd digits for each digit length from 1 to num_digits - 1
    count = 0
    for d in range(1, num_digits):
        count += count_odd_digits_up_to_digit_length(d)

    # Count numbers with odd digits for the current digit length
    count += count_odd_digits_up_to_digit_length(num_digits)

    return count

