def count_odd_digit_numbers(N):
    def count_digits(x):
        return len(str(x))

    def is_odd_digit(x):
        return count_digits(x) % 2 == 1

    def find_last_odd_digit_number(n):
        low, high = 1, n
        while low < high:
            mid = (low + high + 1) // 2
            if is_odd_digit(mid):
                low = mid
            else:
                high = mid - 1
        return low

    return find_last_odd_digit_number(N)

